def strip(t):
    out=[];i=0;n=len(t);depth=0
    while i<n:
        if depth>0:
            if t.startswith('/-',i): depth+=1;i+=2;continue
            if t.startswith('-/',i): depth-=1;i+=2;continue
            i+=1;continue
        if t.startswith('/-',i): depth=1;i+=2;continue
        if t.startswith('--',i):
            j=t.find('\n',i); i=n if j<0 else j; continue
        if t[i]=='"':
            out.append('"');i+=1
            while i<n:
                if t[i]=='\\': i+=2;continue
                if t[i]=='"': out.append('"');i+=1;break
                i+=1
            continue
        out.append(t[i]);i+=1
    return ''.join(out)
